Asynchronous `connect` function

## This would solve...

A compatibility API with the native `http.Agent`s.

## The implementation should look like...

It can accept a `callback` argument or be `await`ed.

## Additional context

A Proof-of-Concept of the compatibility API. Unfortunately it works only once because undici doesn't support asynchronous `connect` function yet. It's very important that we use `agent.addRequest` and not `agent.createConnection` because many agents implement the low-level things on their own and expose only `addRequest`.

```js
const {Agent: HttpsAgent} = require('https');
const {Agent} = require('.');
const {kClients} = require('./lib/core/symbols');

class MyAgent extends HttpsAgent {
	createConnection(...args) {
		console.log('HttpsAgent');

		return super.createConnection(...args);
	}
}

const httpsAgent = new MyAgent();
const agent = new Agent();

// This should be inside `options.connect` but undici doesn't support async `connect` function yet
const dispatch = (agent, options, handlers) => {
	const ref = agent[kClients].get(options.origin);
	const dispatcher = ref ? ref.deref() : null;

	if (dispatcher) {
		agent.dispatch(options, handlers);
		return;
	}

	const isHttps = options.protocol === 'https:';

	if (!options.port) {
		options.port = isHttps ? 443 : 80;
	}

	httpsAgent.addRequest({
		onSocket: (socket, error) => {
			if (error) {
				handlers.onError(error);
				return;
			}

			socket.setNoDelay(true);
			socket.unref();

			options.connect = (_, onConnect) => {
				if (socket.readyState === 'open') {
					queueMicrotask(onConnect);
				} else {
					socket.once(isHttps ? 'secureConnect' : 'connect', onConnect);
				}

				return socket;
			};

			agent.dispatch(options, handlers);
		},
		getHeader: header => {
			return undefined;
		},
		timeout: 0
	}, options);
};

const chunks = [];

dispatch(agent, {
	protocol: 'https:',
	host: 'httpbin.org',
	origin: 'https://httpbin.org',
	path: '/anything',
	method: 'GET'
}, {
	onConnect() {
		console.log('Connected!');
	},
	onHeaders(statusCode, headers) {
		console.log(statusCode);
	},
	onData(chunk) {
		chunks.push(chunk);
	},
	onComplete() {
		console.log(Buffer.concat(chunks).toString());
	},
	onError(error) {
		console.error(error);
	}
});
```

